/**
 * Standalone prototype shell (pure text generator).
 *
 * `prototype/options-menu.js` is a dependency-free script an app drops in with ONE tag:
 *   <script src="prototype/options-menu.js"></script>
 * It adds a top-left "Options" button (device view, design style, button type). Choices apply to every local
 * design at once through <html data-uiux-style data-button-style data-device> + CSS variables, are remembered in
 * localStorage, and are announced with a `uiux:options-change` event. No backend, database or network is used:
 * style files are plain static files under `<root>/source/`.
 */
export const DEVICES = [
  { key: 'responsive', label: 'Responsive (full window)', width: 0, height: 0 },
  { key: 'phone', label: 'Phone 390×844', width: 390, height: 844 },
  { key: 'tablet', label: 'Tablet 820×1180', width: 820, height: 1180 },
  { key: 'laptop', label: 'Laptop 1280×800', width: 1280, height: 800 },
  { key: 'desktop', label: 'Desktop 1440×900', width: 1440, height: 900 }
];

export function optionsMenuJs({ root = 'uiux', designStyles = [], buttonStyles = [], defaultStyle, defaultButton }) {
  const cfg = {
    base: `${root}/source`,
    devices: DEVICES,
    designStyles: designStyles.map(s => ({ key: s.key, label: s.label || s.key, mode: s.mode || '' })),
    buttonStyles: buttonStyles.map(b => ({ key: b.key, label: b.label || b.key })),
    defaultStyle: defaultStyle || designStyles[0]?.key || '',
    defaultButton: defaultButton || buttonStyles[0]?.key || ''
  };
  return `/* Generated by kyrpy-uiux (do not edit; re-generated by uiux_init / uiux_import_styles). */
(function () {
  'use strict';
  var CFG = ${JSON.stringify(cfg)};
  var KEY = 'uiux.prototype.options';
  var base = (window.UIUX_BASE || CFG.base).replace(/\\/$/, '');
  var html = document.documentElement;
  var state = { device: 'responsive', style: CFG.defaultStyle, button: CFG.defaultButton };
  try { Object.assign(state, JSON.parse(localStorage.getItem(KEY) || '{}')); } catch (e) { /* storage may be blocked */ }
  function has(list, k) { return list.some(function (x) { return x.key === k; }); }
  if (!has(CFG.devices, state.device)) state.device = 'responsive';
  if (!has(CFG.designStyles, state.style)) state.style = CFG.defaultStyle;
  if (!has(CFG.buttonStyles, state.button)) state.button = CFG.defaultButton;

  function link(id, href) {
    var el = document.getElementById(id);
    if (!el) { el = document.createElement('link'); el.id = id; el.rel = 'stylesheet'; document.head.appendChild(el); }
    if (el.getAttribute('href') !== href) el.setAttribute('href', href);
  }
  function apply() {
    var d = CFG.devices.filter(function (x) { return x.key === state.device; })[0];
    html.setAttribute('data-uiux-style', state.style);
    html.setAttribute('data-button-style', state.button);
    html.setAttribute('data-device', state.device);
    html.style.setProperty('--uiux-device-width', d && d.width ? d.width + 'px' : '100%');
    html.style.setProperty('--uiux-device-height', d && d.height ? d.height + 'px' : '100vh');
    link('uiux-style-css', base + '/adapters/web/' + state.style + '/tokens.css');
    link('uiux-button-style-css', base + '/tokens/button-styles.css');
    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
    window.dispatchEvent(new CustomEvent('uiux:options-change', { detail: Object.assign({}, state) }));
  }

  var css = document.createElement('style');
  css.textContent = '#uiux-options{position:fixed;top:8px;left:8px;z-index:2147483000;font:13px/1.4 system-ui,sans-serif}' +
    '#uiux-options>button{min-width:44px;min-height:44px;border-radius:50%;border:1px solid #8886;background:#fffd;color:#111;cursor:pointer;font-size:20px;box-shadow:0 2px 8px #0003}' +
    '#uiux-options .panel{display:none;margin-top:6px;padding:10px;width:240px;max-width:calc(100vw - 24px);background:#fffe;color:#111;border:1px solid #8886;border-radius:12px;box-shadow:0 6px 24px #0004;backdrop-filter:blur(8px)}' +
    '#uiux-options.open .panel{display:block}#uiux-options label{display:block;margin:6px 0 2px;font-weight:600}' +
    '#uiux-options select{width:100%;min-height:36px}' +
    'html[data-device]:not([data-device="responsive"]) body{max-width:var(--uiux-device-width);min-height:var(--uiux-device-height);margin-inline:auto;box-shadow:0 0 0 1px #8886,0 12px 40px #0004}';
  document.head.appendChild(css);

  function select(label, id, list, value) {
    return '<label for="' + id + '">' + label + '</label><select id="' + id + '">' + list.map(function (x) {
      return '<option value="' + x.key + '"' + (x.key === value ? ' selected' : '') + '>' + x.label + (x.mode ? ' (' + x.mode + ')' : '') + '</option>';
    }).join('') + '</select>';
  }
  function mount() {
    if (document.getElementById('uiux-options')) return;
    var box = document.createElement('div');
    box.id = 'uiux-options';
    box.innerHTML = '<button type="button" aria-label="Options" aria-expanded="false" title="Options">⚙</button><div class="panel" role="dialog" aria-label="Prototype options">' +
      select('Device view', 'uiux-opt-device', CFG.devices, state.device) +
      select('Style view', 'uiux-opt-style', CFG.designStyles, state.style) +
      select('Button type', 'uiux-opt-button', CFG.buttonStyles, state.button) + '</div>';
    document.body.appendChild(box);
    var btn = box.querySelector('button');
    btn.addEventListener('click', function () { var o = box.classList.toggle('open'); btn.setAttribute('aria-expanded', String(o)); });
    [['uiux-opt-device', 'device'], ['uiux-opt-style', 'style'], ['uiux-opt-button', 'button']].forEach(function (p) {
      box.querySelector('#' + p[0]).addEventListener('change', function (e) { state[p[1]] = e.target.value; apply(); });
    });
  }
  window.UIUX_OPTIONS = { get: function () { return Object.assign({}, state); }, set: function (patch) { Object.assign(state, patch); apply(); } };
  apply();
  if (document.body) mount(); else document.addEventListener('DOMContentLoaded', mount);
})();
`;
}
